// Generated by build.mjs: precaches the whole site so it works offline.
// Pages: network first (fresh recipes when online), cache when offline or slow.
// CSS/JS/icons: cache first; a new build gets a new VERSION and refills the cache.
const VERSION = '__VERSION__';
const PRECACHE = __PRECACHE__;
const CACHE = `rezepte-${VERSION}`;
const NETWORK_TIMEOUT_MS = 3000;

self.addEventListener('install', (e) => {
  // cache: 'reload' bypasses the HTTP cache (GitHub Pages sends max-age=600),
  // otherwise a new worker could precache the previous build's files
  e.waitUntil(caches.open(CACHE)
    .then((c) => c.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('rezepte-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

async function networkFirst(request) {
  const c = await caches.open(CACHE);
  const network = fetch(request, { cache: 'no-cache' }).then((res) => {
    if (res.ok) c.put(request, res.clone());
    return res;
  });
  network.catch(() => {}); // offline: handled below
  const timeout = new Promise((resolve) => setTimeout(resolve, NETWORK_TIMEOUT_MS));
  try {
    const res = await Promise.race([network, timeout]);
    if (res) return res;
  } catch { /* offline */ }
  const hit = (await c.match(request, { ignoreSearch: true })) ?? (await c.match('./'));
  return hit ?? network; // nothing cached: keep waiting for the network
}

async function cacheFirst(request) {
  const c = await caches.open(CACHE);
  return (await c.match(request, { ignoreSearch: true })) ?? fetch(request);
}

self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(e.request.mode === 'navigate' ? networkFirst(e.request) : cacheFirst(e.request));
});
